import { array } from "numpy-ts";
import { isNDArray, numeric } from "./arrays.js";
import { config } from "../_config/utils.js";
import { seek_full_path_from_defaults } from "./file_ops.js";
export function change_to_rgba_array(image, dtype = "uint8") {
    void dtype;
    let voxels;
    if (isNDArray(image)) {
        const shape = image.shape;
        const raw = image.toArray();
        if (shape.length <= 2) {
            const flat = (Array.isArray(raw) ? raw : [raw]);
            const flatNums = flat.flatMap((item) => Array.isArray(item) ? item.map(numeric) : [numeric(item)]);
            const cols = shape.length === 2 ? shape[1] : flatNums.length;
            const grid = [];
            for (let i = 0; i < flatNums.length; i += cols)
                grid.push(flatNums.slice(i, i + cols));
            voxels = grid.map((row) => row.map((v) => [v]));
        }
        else {
            voxels = raw.map((row) => row.map((pixel) => (Array.isArray(pixel) ? pixel : [pixel]).map(numeric)));
        }
    }
    else if (Array.isArray(image) && image.length > 0 && Array.isArray(image[0])) {
        const grid = image;
        if (Array.isArray(grid[0][0])) {
            voxels = grid.map((row) => row.map((pixel) => (Array.isArray(pixel) ? pixel : [pixel]).map(numeric)));
        }
        else {
            voxels = grid.map((row) => row.map((v) => [numeric(v)]));
        }
    }
    else {
        const flat = image.map(numeric);
        voxels = [flat.map((v) => [v])];
    }
    let channels = voxels[0]?.[0]?.length ?? 0;
    if (channels === 1) {
        voxels = voxels.map((row) => row.map((pixel) => [pixel[0] ?? 0, pixel[0] ?? 0, pixel[0] ?? 0]));
        channels = 3;
    }
    if (channels === 3) {
        voxels = voxels.map((row) => row.map((pixel) => [...pixel, 255]));
    }
    // NOTE: Python's change_to_rgba_array only uses `dtype` for the appended
    // alpha channel (`255 * np.ones(..., dtype=dtype)`) and returns the array
    // with its original dtype otherwise (float input stays float). So we must
    // NOT cast the whole array to `dtype` here: astype("uint8") would truncate
    // float pixels (e.g. 0.5 -> 0).
    return array(voxels);
}
export function get_full_vector_image_path(image_file_name) {
    return seek_full_path_from_defaults(image_file_name, config.getDir("assets_dir"), [".svg"]);
}
export function get_full_raster_image_path(image_file_name) {
    return seek_full_path_from_defaults(image_file_name, config.getDir("assets_dir"), [".jpg", ".jpeg", ".png", ".gif", ".ico"]);
}
